use std::io::{Read,Write};
fn quote(s:&str)->String {let mut out=String::from("\"");for c in s.chars(){match c {'"'=>out.push_str("\\\""),'\\'=>out.push_str("\\\\"),'\n'=>out.push_str("\\n"),'\r'=>out.push_str("\\r"),'\t'=>out.push_str("\\t"),c if (c as u32)<32=>out.push_str(&format!("\\u{:04x}",c as u32)),c=>out.push(c)}}out.push('"');out}
fn main(){let args:Vec<String>=std::env::args().collect();let mut input=String::new();std::io::stdin().read_to_string(&mut input).unwrap();let command=args.get(1).map(String::as_str).unwrap_or("");let id=args.iter().position(|s|s=="--batch-id").and_then(|i|args.get(i+1)).map(String::as_str).unwrap_or("");
    if let Ok(expected)=std::env::var("MINDTRAIL_EXPECT_STDIN") {if input!=expected {std::process::exit(12)}}
    match id {"test-error"=>{println!(r#"{{"error":{{"code":"seq_gap","message":"missing","expected_seq":2,"offending_seq":3,"last_seq":1,"index":0}}}}"#);std::process::exit(1)},"error-two"=>{println!(r#"{{"error":{{"code":"seq_gap","message":"missing"}}}}"#);std::process::exit(2)},"bad-json"=>print!("{{}}{{}}"),"duplicate"=>print!(r#"{{"status":"queued","status":"queued","batch_id":"duplicate","session":"s"}}"#),"bad-shape"=>print!(r#"{{"status":"committed"}}"#),"wrong-id"=>print!(r#"{{"status":"queued","batch_id":"different","session":"s"}}"#),"wrong-session"=>print!(r#"{{"status":"queued","batch_id":"wrong-session","session":"other"}}"#),"wrong-count"=>print!(r#"{{"status":"committed","batch_id":"wrong-count","session":"s","receipt":{{"accepted":0,"duplicates":0,"last_seq":1}}}}"#),"low-watermark"=>print!(r#"{{"status":"committed","batch_id":"low-watermark","session":"s","receipt":{{"accepted":1,"duplicates":0,"last_seq":0}}}}"#),"valid-committed"=>print!(r#"{{"status":"committed","batch_id":"valid-committed","session":"s","receipt":{{"accepted":1,"duplicates":0,"last_seq":1}}}}"#),"error-zero"=>print!(r#"{{"error":{{"code":"seq_gap","message":"x"}}}}"#),"invalid-utf8"=>{let _=std::io::stdout().write_all(&[0xff]);},"exit"=>{println!(r#"{{"status":"queued","batch_id":"exit","session":"s"}}"#);std::process::exit(7)},"hang"=>{std::thread::sleep(std::time::Duration::from_millis(900));if let Ok(path)=std::env::var("MINDTRAIL_FIXTURE_SURVIVAL_MARKER"){let _=std::fs::write(path,b"alive");}std::thread::sleep(std::time::Duration::from_secs(30))},"flood"=>{let mut out=std::io::stdout().lock();let block=vec![b'x';8192];for _ in 0..64 {if out.write_all(&block).is_err(){break}}},"stderr-flood"=>{let mut out=std::io::stderr().lock();let block=vec![b'x';8192];for _ in 0..64 {if out.write_all(&block).is_err(){break}}},_ if command=="flush"=>println!(r#"{{"committed":1,"pending":2,"blocked":3}}"#),_=>println!("{{\"status\":\"queued\",\"batch_id\":{},\"session\":\"s\"}}",quote(id))}
}
